#include <stdlib.h>
#include <string.h>

char **buildargv(char *input) {
  static char *arglist[256];
  int          numargs = 0;

  while (1) {
    while (*input == ' ')
      input++;
    if (*input == 0)
      break;
    arglist[numargs++] = input;
    while (*input != ' ' && *input != 0)
      input++;
    if (*input == 0)
      break;
    *(input++) = 0;
  }
  arglist[numargs] = NULL;
  return arglist;
}

int main() {
  char **args;
  char   input[256];
  int    i;

  strcpy(input, " a b");
  args = buildargv(input);

  if (strcmp(args[0], "a"))
    abort();
  if (strcmp(args[1], "b"))
    abort();
  if (args[2] != NULL)
    abort();

  exit(0);
}


